 42	function computeHeuristicScore(
 43	  text: string,
 44	  inboundCount: number,
 45	  unreadCount: number,
 46	  ageHours: number | null,
 47	): { score: number; reasons: string[] } {
 48	  let score = 18;
 49	  const reasons: string[] = [];
 50	
 51	  if (inboundCount >= 2) {
 52	    score += Math.min(28, inboundCount * 6);
 53	    reasons.push('multiple_recent_inbounds');
 54	  }
 55	  if (unreadCount > 0) {
 56	    score += unreadCount >= 3 ? 15 : 12;
 57	    reasons.push('has_unread_backlog');
 58	  }
 59	  if (PRE_C__O_VALOR_QUANTO_O_RE.test(text)) {
 60	    score += 16;
 61	    reasons.push('asked_price');
 62	  }
 63	  if (QUERO_VOU_COMPRAR_ME_MA_RE.test(text)) {
 64	    score += 24;
 65	    reasons.push('buying_signal');
 66	  }
 67	  if (PROBLEMA_ERRO_SUPORTE_A_RE.test(text)) {
 68	    score -= 12;
 69	    reasons.push('support_or_complaint');
 70	  }
 71	  if (ageHours !== null && ageHours <= 72) {
 72	    score += 10;
 73	    reasons.push('recent_activity');
 74	  }
 75	  if (ageHours !== null && ageHours > 24 * 7) {
 76	    score -= 10;
 77	    reasons.push('stale_interest');
 78	  }
 79	
 80	  score = Math.max(0, Math.min(100, Math.round(score)));
 81	  return { score, reasons };
 82	}
