291	export function inferHeuristicDemographics(text: string): {
292	  gender: string;
293	  ageRange: string;
294	  location: string;
295	  confidence: number;
296	} {
297	  const normalized = String(text || '').toLowerCase();
298	
299	  let gender = 'UNKNOWN';
300	  if (B_SOU_MULHER_MINHA_ESPO_RE.test(normalized)) {
301	    gender = 'FEMININO';
302	  } else if (B_SOU_HOMEM_MEU_MARIDO_RE.test(normalized)) {
303	    gender = 'MASCULINO';
304	  }
305	
306	  const explicitAge = normalized.match(B__D_2___S_ANOS_B_RE);
307	  let ageRange = 'UNKNOWN';
308	  if (explicitAge) {
309	    const age = Number(explicitAge[1]);
310	    if (age >= 18 && age <= 24) {
311	      ageRange = '18-24';
312	    } else if (age <= 34) {
313	      ageRange = '25-34';
314	    } else if (age <= 44) {
315	      ageRange = '35-44';
316	    } else if (age <= 54) {
317	      ageRange = '45-54';
318	    } else if (age > 54) {
319	      ageRange = '55+';
320	    }
321	  }
322	
323	  const locationMatch = normalized.match(B___SOU_DE_MORO_EM_AQUI_RE) || null;
324	  const location = locationMatch?.[1] ? String(locationMatch[1]).trim() : 'UNKNOWN';
325	
326	  let confidence = 0;
327	  if (gender !== 'UNKNOWN') {
328	    confidence = Math.max(confidence, 0.35);
329	  }
330	  if (ageRange !== 'UNKNOWN') {
331	    confidence = Math.max(confidence, 0.55);
332	  }
333	  if (location !== 'UNKNOWN') {
334	    confidence = Math.max(confidence, 0.45);
335	  }
336	
337	  return {
338	    gender,
339	    ageRange,
340	    location,
341	    confidence,
342	  };
